import cpmpy as cp
import json
from itertools import combinations

# First clue: product of ages is 36
# Find all possible triplets (a1, a2, a3) where a1*a2*a3 = 36 and a1 >= a2 >= a3 >= 1
possible_ages = []
for a1 in range(1, 37):
    for a2 in range(1, a1+1):
        for a3 in range(1, a2+1):
            if a1 * a2 * a3 == 36:
                possible_ages.append((a1, a2, a3))

# Second clue: sum of ages equals number of windows (but this wasn't enough information)
# So we need to find sums that appear more than once in possible_ages
sum_counts = {}
for ages in possible_ages:
    s = sum(ages)
    if s in sum_counts:
        sum_counts[s].append(ages)
    else:
        sum_counts[s] = [ages]

# The ambiguous sums are those with multiple possible age triplets
ambiguous_sums = [s for s in sum_counts if len(sum_counts[s]) > 1]

# Third clue: there is an oldest son (no twins among the oldest)
# So we look for triplets in ambiguous sums where a1 > a2
valid_triplets = []
for s in ambiguous_sums:
    for triplet in sum_counts[s]:
        if triplet[0] > triplet[1]:  # oldest is unique
            valid_triplets.append(triplet)

# There should be exactly one valid triplet left
assert len(valid_triplets) == 1
solution = {'A1': valid_triplets[0][0], 'A2': valid_triplets[0][1], 'A3': valid_triplets[0][2]}

print(json.dumps(solution))
